/*
	Modern rug #genuary15 #genuary #genuary2515
	Design a rug.
	https://openprocessing.org/sketch/2511119
	#p5js #creativecoding #generativeart 
*/

let MAR, PAD, SX, SY, pal;
let nX, nY;
let NUM_SVG_GROUPS, SVG_GRPS;

function setup() {
	// createCanvas(S = max(windowWidth, windowHeight), S);
	createCanvas(windowWidth, windowHeight);
	const S = max(windowWidth, windowHeight)
	describe("");
	background(2, 2, 12);
	stroke(32);
	strokeWeight(2);
	noFill();

	// init palette and svg groups
	pal = random(palettes);
	NUM_SVG_GROUPS = pal.length;
	SVG_GRPS = []; for (let i = 0; i < NUM_SVG_GROUPS; i++) SVG_GRPS[i] = [];

	PAD = ~~random(6, 12)
	MAR = S * random(0.05, 0.1);
	SX = width - 2 * MAR;
	SY = height - 2 * MAR;

	SPOT = {x: randomGaussian(width/2, 50), y: randomGaussian(height/2, 50)}
	FRCTS = [random(0.3, 0.7), random(0.3, 0.7), random(0.3, 0.7), random(0.3, 0.7)]; // north, east, south, west

	nx = ~~random(4, 11);
	ny = ~~random(5, 13);
	// console.log(`nx ${nx}, ny ${ny}`);

	// fraction method with random
	let sumX = [];
	let arrRandXFr = [...Array(ny)].map((y) => [...Array(nx-1)].map((x) => random(0.3, 0.7)));
	arrRandXFr.forEach((arr) => {
  	sumX.push(arr.reduce((acc, val) => acc + val, 0));
	});
	for (let i = 0; i < ny; i++) for (let j = 0; j < nx; j++) arrRandXFr[i][j] /= sumX[i];
	for (let i = 0; i < ny; i++) {
		let acc = 0;
		for (let j = 0; j < nx; j++) {
			acc += arrRandXFr[i][j];
			arrRandXFr[i][j] = acc;
		}
		arrRandXFr[i].unshift(0);
	}

	let sumY = [];
	let arrRandYFr = [...Array(nx)].map((x) => [...Array(ny-1)].map((y) => random(0.3, 0.7)));
	arrRandYFr.forEach((arr) => {
  	sumY.push(arr.reduce((acc, val) => acc + val, 0));
	});
	for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) arrRandYFr[i][j] /= sumY[i];
	for (let i = 0; i < nx; i++) {
		var acc = 0;
		for (let j = 0; j < ny; j++) {
			acc += arrRandYFr[i][j];
			arrRandYFr[i][j] = acc;
		}
		arrRandYFr[i].unshift(0);
	}

	PTS = [...Array(ny)].map((arr) => [...Array(nx)].map((it) => 0));
	for (let j = 0; j < ny; j++) {
		for (let i = 0; i < nx; i++) {
			let x = arrRandXFr[j][i] * SX + MAR;
			let y = arrRandYFr[i][j] * SY + MAR;
			PTS[j][i] = {x, y};
		}
	}
	// console.log(PTS);
	loop();
}

function draw() {
	const NUM = ~~(SX / nx / PAD);

	for (let j = 0; j < ny-1; j++) {
		for (let i = 0; i < nx-1; i++) {
			const p1 = PTS[j][i];
			const p2 = PTS[j][i+1];
			const p3 = PTS[j+1][i];
			const p4 = PTS[j+1][i+1];
			const clrIdx = ~~random(pal.length);
			stroke(pal[clrIdx])
			drawTrapezLines(p1, p2, p3, p4, NUM);
		}
	}

	// noLoop() removed for animation
}

function drawTrapezLines(tl, tr, bl, br, n = 10, clrIdx = 0) {
	let svgStr = "";
	for (let i = 0; i < n; i++) {
		const f = i/n;
		var p1 = pLerp(tl, tr, f);
		var p2 = pLerp(bl, br, f);
		line(p1.x, p1.y, p2.x, p2.y);
		svgStr += `<line x1="${nf(p1.x,0,3)}" y1="${nf(p1.y,0,3)}" x2="${nf(p2.x,0,3)}" y2="${nf(p2.y,0,3)}" />\n`;
	}

	const svgGr = `<g stroke="${pal[clrIdx]}">\n${svgStr}</g>\n`
	SVG_GRPS[clrIdx].push(svgGr);
}

function pLerp(p1, p2, f) {
	var x = lerp(p1.x, p2.x, f);
	var y = lerp(p1.y, p2.y, f);
	return {x, y};
}

function mousePressed() {
	if (mouseButton != RIGHT) setup();
}

function keyPressed() {
	if (key === "s") {
		// console.log(key);

		let grStr = "";
		var clrIdx = 0;
		for (const gr of SVG_GRPS) {
			grStr += `<g>\n`;
			for (const el of gr) {
				grStr += `${el}\n`;
			}
			grStr += `</g>\n`;
		}
		var svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n${grStr}\n</svg>`;
		// console.log(svgStr)
		save(svgStr.split("\n"), "epi_modern_rug.svg.txt")

	}
}
